from typing import TypedDict, Any


class ResearchState(TypedDict):
    # Original research query
    research_question: str

    # Questions generated by the Research Manager
    subquestions: list[str]

    # Evidence retrieved by the Researcher
    research_results: list[dict[str, Any]]

    # Generated research report
    synthesis: str

    # Results from the Fact Checker
    fact_check_results: list[dict[str, Any]]

    # Evaluation from the Critic
    critique: dict[str, Any]

    # Number of research iterations completed
    iteration_count: int

    # Maximum number of allowed iterations
    max_iterations: int

    # Final report
    final_report: str

    # accepted or max_iterations_reached
    completion_status: str

    # Paper IDs successfully processed across all research iterations
    processed_paper_ids: list[str]